#pragma once
#include <cstdint>
#include <string>
#include <vector>

namespace iov::scheduling {

// One sub-task of a vehicle's application.
struct Task {
    uint64_t id = 0;                      // globally unique
    std::vector<uint64_t> dependencies;   // ids of tasks that must finish first
    double workload_mcycles = 0.0;        // CPU work, in mega-cycles
    double data_kb = 0.0;                 // input data uploaded from the vehicle, in KB
};

// A DAG of tasks generated by one vehicle at one moment.
struct Dag {
    int id = 0;
    double arrival_s = 0.0;
    std::string owner_vehicle;
    std::vector<Task> tasks;  // topologically ordered: dependencies always have smaller index
};

// A task whose dependencies are all finished and that is waiting to be
// sent to a server.
struct ReadyTask {
    uint64_t task_id = 0;
    int dag_id = 0;
    double ready_time_s = 0.0;  // when its last dependency finished (or DAG arrival)
};

// Strategy interface: decides the order in which waiting tasks (from all
// DAGs) get a chance to be dispatched. Order matters whenever there are
// more waiting tasks than free server slots.
class ITaskScheduler {
public:
    virtual ~ITaskScheduler() = default;
    virtual std::string name() const = 0;

    // Hooks so a policy can precompute per-DAG data (e.g. ranks).
    virtual void onDagArrival(const Dag& /*dag*/) {}
    virtual void onDagFinished(const Dag& /*dag*/) {}

    // Returns the waiting tasks in the order they should be dispatched.
    virtual std::vector<ReadyTask> order(std::vector<ReadyTask> ready) = 0;
};

}  // namespace iov::scheduling
